/**
 * Entry point to game application.
 *
 * This code is going to be boilerplate for any Webgl project, as here we set
 * global references to canvas, debug, adn rendering context objects.
 */
import debugRef from "@context/debug";
import canvasRef from "@context/canvas";
import renderRef from "@context/render_context";
import ballGameEntry from "@game/game";
document.addEventListener("DOMContentLoaded", async () => {
    /* GET CANVAS ELEMENT */
    const cv = document.getElementById("my_canvas");
    /* GET DEBUG ELEMENT AND SAVE TO SINGLETON */
    const debug = document.getElementById("debug-container");
    if (!debug) {
        throw new Error("Debug container could not be found");
    }
    debugRef.elementRef = debug;
    if (!cv) {
        debugRef.elementRef.innerText = "No canvas element found";
        throw new Error("Canvas could not be found");
    }
    canvasRef.elementRef = cv;
    /* GET RENDERING CONTEXT */
    const gl = cv.getContext("webgl2");
    if (!gl) {
        debugRef.elementRef.innerText = "Error: webgl context not found.";
        throw new Error("");
    }
    renderRef.elementRef = gl;
    /* LOAD GAME HERE */
    try {
        await ballGameEntry();
        /* PROGRAM RAN SUCCESSFULLY FLAG */
        // debugRef.elementRef.innerText = "Program ran successfully";
    }
    catch (e) {
        debugRef.elementRef.innerText = e;
    }
});
