import renderRef from "@context/render_context";
import debugRef from "@context/debug";
import canvasRef from "@context/canvas";
/**
 * Setup constant attributes such as clear canvas values and clip space mapping
 * @returns void
 *  */
const setup = () => {
    const cv = canvasRef.elementRef;
    if (!cv) {
        if (!debugRef.elementRef)
            throw new Error('No canvas or debug element');
        debugRef.elementRef.innerText = "No canvas element";
        throw new Error('No canvas element');
    }
    const gl = renderRef.elementRef;
    if (!gl) {
        if (!debugRef.elementRef)
            throw new Error('No gl or debug element');
        debugRef.elementRef.innerText = "No gl element";
        throw new Error('No gl element');
    }
    /* Resize CSS drawig buffer to roughly match actual screen pixels */
    const dpr = window.devicePixelRatio || 1;
    cv.width = Math.round(cv.clientWidth * dpr);
    cv.height = Math.round(cv.clientHeight * dpr);
    /* CONVERT TO CLIP SPACE */
    gl.viewport(0, 0, cv.width, cv.height);
    /* CLEAR CANVAS */
    gl.clearColor(1.0, 1.0, 1.0, 1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);
    canvasRef.elementRef = cv;
    renderRef.elementRef = gl;
};
export default setup;
