/**
 * Main entry point to ball game.
 *
 * Set up game object and load in level in debug console, and perform some basic
 * set up
 */
import setup from "./utils/setup";
import GameState from "./state/gameState";
/* WILL WRITE SCRIPT TO ALLOW USER TO CHOOSE LEVEL */
const ballGameEntry = async () => {
    /* SET UP RENDERER DEFAULTS */
    setup();
    /* INITIALISE GAME STATE OBJECT */
    await GameState.setLevel();
    /* SET DEFAULT CAMERA SETTINGS  */
    GameState.setProjectionSettings();
    /* LOAD ASSETS HERE */
    /* Attach event listeners to document */
    GameState.attachGenericListeners();
    /* Start rendering loop */
    GameState.startGame();
};
export default ballGameEntry;
