import debugRef from "@context/debug";
import renderRef from "@context/render_context";
import { glMatrix, mat4 } from "gl-matrix";
import canvasRef from "@context/canvas";
/**
 * manage interface with level, manages rendering loop, and user inputs,
 * and other global variables. Game state manages level object state directly
 * on user input and other events
 *
 * @class
 */
class GameState {
    /**
     * @private
     * @static
     * @type {number}
     * @description
     */
    static _level = null;
    /**
     * Event listener states
     */
    static isUpArrowPressed = false;
    static isDownArrowPressed = false;
    static isRightArrowPressed = false;
    static isLeftArrowPressed = false;
    static isClick = false;
    static isSpacePressed = false;
    static isWPressed = false;
    static isAPressed = false;
    static isSPressed = false;
    static isDPressed = false;
    static mouseCoords = { x: 0, y: 0 };
    /**
     * DEfault settings
     */
    static projectionMatrix = null;
    /**
     * Sets current game level
     */
    static async setLevel() {
        const levelTwo = await import("../levels/level_two/levelTwoMain").then((module) => module.default);
        GameState._level = levelTwo;
    }
    /**
     *  Attempt to attach event listeners to window
     * @returns void
     */
    static attachGenericListeners() {
        document.addEventListener("keydown", ({ key }) => {
            switch (key) {
                case "ArrowUp":
                    GameState.isUpArrowPressed = true;
                    break;
                case "ArrowDown":
                    GameState.isDownArrowPressed = true;
                    break;
                case "ArrowLeft":
                    GameState.isLeftArrowPressed = true;
                    break;
                case "ArrowRight":
                    GameState.isRightArrowPressed = true;
                    break;
                case " ":
                    GameState.isSpacePressed = true;
                    break;
                case "w":
                    GameState.isWPressed = true;
                    break;
                case "a":
                    GameState.isAPressed = true;
                    break;
                case "s":
                    GameState.isSPressed = true;
                    break;
                case "d":
                    GameState.isDPressed = true;
                    break;
                default:
                    break;
            }
        });
        document.addEventListener("keyup", ({ key }) => {
            switch (key) {
                case "ArrowUp":
                    GameState.isUpArrowPressed = false;
                    break;
                case "ArrowDown":
                    GameState.isDownArrowPressed = false;
                    break;
                case "ArrowLeft":
                    GameState.isLeftArrowPressed = false;
                    break;
                case "ArrowRight":
                    GameState.isRightArrowPressed = false;
                    break;
                case " ":
                    GameState.isSpacePressed = false;
                    break;
                case "w":
                    GameState.isWPressed = false;
                    break;
                case "a":
                    GameState.isAPressed = false;
                    break;
                case "s":
                    GameState.isSPressed = false;
                    break;
                case "d":
                    GameState.isDPressed = false;
                    break;
                default:
                    break;
            }
        });
        document.addEventListener("mousedown", () => {
            GameState.isClick = true;
        });
        document.addEventListener("mouseup", () => {
            GameState.isClick = false;
        });
        document.addEventListener("mousemove", ({ clientX, clientY }) => {
            GameState.mouseCoords = {
                x: clientX,
                y: clientY,
            };
        });
    }
    /**
     * Possibly add some custom event listeners, assigned by LevelAbstract
     */
    /**
     * Start game by calling render function
     * @returns void
     */
    static startGame() {
        /* Pre launch checks here if necessary */
        requestAnimationFrame(GameState.updateState);
    }
    /**
     * Update game state per render
     */
    static updateState(timeStamp) {
        /* LOGIC GOES HERE */
        renderRef.elementRef.clearColor(1.0, 1.0, 1.0, 1.0);
        renderRef.elementRef.clear(renderRef.elementRef.COLOR_BUFFER_BIT |
            renderRef.elementRef.DEPTH_BUFFER_BIT);
        renderRef.elementRef.enable(renderRef.elementRef.DEPTH_TEST);
        try {
            if (GameState._level) {
                GameState._level.update({
                    isUpArrowPressed: GameState.isUpArrowPressed,
                    isDownArrowPressed: GameState.isDownArrowPressed,
                    isRightArrowPressed: GameState.isRightArrowPressed,
                    isLeftArrowPressed: GameState.isLeftArrowPressed,
                    isWPressed: GameState.isWPressed,
                    isAPressed: GameState.isAPressed,
                    isSPressed: GameState.isSPressed,
                    isDPressed: GameState.isDPressed,
                    isClick: GameState.isClick,
                    isSpacePressed: GameState.isSpacePressed,
                    mouseCoords: GameState.mouseCoords,
                });
            }
        }
        catch (e) {
            debugRef.elementRef.innerText = e;
        }
        requestAnimationFrame(GameState.updateState);
    }
    /**
     * Matrix to project world space co-ordinates to clip space
     * @param fov
     * @param nearClip
     * @param farClip
     */
    static setProjectionSettings(fov = 45, nearClip = 0.1, farClip = 1000) {
        /* Create new unit matrix */
        const projectionMatrix = mat4.create();
        mat4.perspective(projectionMatrix, glMatrix.toRadian(fov), canvasRef.elementRef?.width / canvasRef.elementRef?.height, nearClip, farClip);
        GameState.projectionMatrix = projectionMatrix;
        if (!GameState._level) {
            throw new Error("Level not assigned to Game State");
        }
        GameState._level.projectionMatrix = projectionMatrix;
    }
}
export default GameState;
